mapper.select:
select
bcr.id,
bcr.compartment_id,
bcr.compartment_name,
bcr.reserve_start_time,
bcr.reserve_end_time,
bcr.reserve_status,
bcr.subscriber_id,
bcr.subscriber_name,
bcr.subscriber_staffid,
bcr.phone,
bcr.combo_id,
bcr.combo_name,
bcr.use_time,
bcr.reserve_source,
bcr.create_time
from bbx_compartment_reserve bcr
JOIN bbx_compartment bc ON bcr.compartment_id = bc.id
where bcr.deleted = 1

    AND bcr.tenant_id =#{condition.tenantId}


    AND bcr.reserve_source =#{condition.reserveSource}


    AND bcr.reserve_status =#{condition.reserveStatus}


    AND bcr.reserve_status in

        #{reserveStatus}



    AND bcr.compartment_id in

        #{compartmentId}



    AND bcr.compartment_id =#{condition.compartmentId}


    AND bc.space_id in

        #{spaceId}



    AND bc.space_id =#{condition.spaceId}


    AND bc.restaurant_id =#{condition.restaurantId}


    AND bcr.combo_id =#{condition.comboId}


    AND (bcr.subscriber_name like concat('%',#{condition.subscriberName},'%') or bcr.subscriber_staffid =#{condition.subscriberName})


    AND bcr.subscriber_id =#{condition.subscriberId}


    AND (#{condition.reserveStartTime} <= bcr.reserve_start_time and #{condition.reserveEndTime} >= bcr.reserve_end_time)

order by bcr.create_time DESC

select
bcr.id,
bcr.compartment_id,
bcr.reserve_start_time,
bcr.reserve_end_time,
bcr.reserve_status
from bbx_compartment_reserve bcr
JOIN bbx_compartment bc ON bcr.compartment_id = bc.id

    bcr.deleted = 1

        AND bcr.tenant_id =#{condition.tenantId}


        AND bcr.reserve_source =#{condition.reserveSource}


        AND bcr.reserve_status =#{condition.reserveStatus}


        AND bcr.reserve_status in

            #{reserveStatus}



        AND bcr.compartment_id in

            #{compartmentId}



        AND bcr.compartment_id =#{condition.compartmentId}


        AND bc.space_id in

            #{spaceId}



        AND bc.space_id =#{condition.spaceId}


        AND bc.restaurant_id =#{condition.restaurantId}


        AND bcr.combo_id =#{condition.comboId}


        AND bcr.subscriber_id =#{condition.subscriberId}


        AND ( bcr.subscriber_name like concat('%',#{condition.subscriberName},'%') or bcr.subscriber_staffid =#{condition.subscriberName} )


        AND (#{condition.reserveStartTime} <= bcr.reserve_start_time and #{condition.reserveEndTime} >= bcr.reserve_end_time)


order by bcr.reserve_start_time

select bcr.id, bcr.compartment_id, bcr.reserve_start_time, bcr.reserve_end_time, bcr.reserve_status from bbx_compartment_reserve bcr where bcr.deleted = 1
and bcr.tenant_id =#{condition.tenantId}
and bcr.id != #{condition.id}
AND bcr.compartment_id =#{condition.compartmentId}
AND bcr.reserve_status in
#{reserveStatus}
and (#{condition.reserveEndTime} >= bcr.reserve_start_time and #{condition.reserveStartTime} <= bcr.reserve_end_time)

SELECT TO_CHAR(TRUNC(reserve_start_time), 'MM-dd') AS time, COUNT(*) AS totalNum FROM bbx_compartment_reserve WHERE deleted = 1
and tenant_id =#{tenantId}
AND reserve_status != 40 AND reserve_start_time >= DATEADD(DAY, -29, SYSDATE) AND reserve_start_time <= SYSDATE GROUP BY TRUNC(reserve_start_time)
